// Generated by esquadro: do not edit. The states of a page, the same
// everywhere: loading the first time (a skeleton of what comes), loading
// again (what was there, dimmed, under a bar), empty, nothing found, an
// error (with a way to try again), not found and not allowed.
import { isApiError } from "@api"
import { AlertTriangle, FileQuestion, Inbox, RotateCw, SearchX, ShieldX } from "lucide-react"
import type { ReactNode } from "react"
import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert"
import { Button } from "@/components/ui/button"
import { Card, CardContent } from "@/components/ui/card"
import { Empty, EmptyContent, EmptyDescription, EmptyHeader, EmptyMedia, EmptyTitle } from "@/components/ui/empty"
import { Skeleton } from "@/components/ui/skeleton"
import { cn } from "@/lib/utils"
import { describe } from "./errors.ts"
import { t } from "./i18n.ts"

/** What a state is about: its icon's color. */
export type StateTone = "default" | "muted" | "warning" | "error"

const TONES: Record<StateTone, string> = {
  default: "bg-primary/10 text-primary ring-primary/5",
  muted: "bg-muted text-muted-foreground ring-muted/50",
  warning: "bg-amber-100 text-amber-600 ring-amber-50 dark:bg-amber-500/20 dark:text-amber-100 dark:ring-amber-500/5",
  error: "bg-destructive/10 text-destructive ring-destructive/5",
}

/**
 * A state with its icon (in a circle of its tone), what happened, and what
 * to do about it. Framed, it is a card of its own: a page with nothing else.
 */
export function StateView({
  icon,
  title,
  description,
  action,
  tone = "default",
  framed = false,
  className,
}: {
  icon: ReactNode
  title: ReactNode
  description?: ReactNode
  action?: ReactNode
  tone?: StateTone
  framed?: boolean
  className?: string
}) {
  return (
    <Empty
      className={cn("gap-5 py-14", framed && "min-h-[60svh] rounded-xl border border-border bg-card", className)}
      role={tone === "error" ? "alert" : "status"}
    >
      <EmptyHeader className="max-w-md gap-3">
        <EmptyMedia className={cn("mb-2 size-16 rounded-full ring-8 [&_svg:not([class*='size-'])]:size-7", TONES[tone])}>{icon}</EmptyMedia>
        <EmptyTitle className="text-lg font-bold tracking-tight text-foreground">{title}</EmptyTitle>
        {description && <EmptyDescription className="text-sm text-muted-foreground">{description}</EmptyDescription>}
      </EmptyHeader>
      {action && <EmptyContent className="flex-row flex-wrap justify-center gap-2">{action}</EmptyContent>}
    </Empty>
  )
}

/** Nothing yet: what will be here, and how to make the first. */
export function EmptyState({ action, className }: { action?: ReactNode; className?: string }) {
  return <StateView icon={<Inbox />} title={t("empty")} description={t("emptyHint")} action={action} className={className} />
}

/** Nothing found for a search or filters, and how to clear them. */
export function NoResultsState({ query, onClear, className }: { query?: string; onClear: () => void; className?: string }) {
  return (
    <StateView
      icon={<SearchX />}
      title={query ? t("noResults", { q: query }) : t("noMatches")}
      description={t("noResultsHint")}
      action={
        <Button variant="outline" onClick={onClear}>
          {query ? t("clearSearch") : t("clearFilters")}
        </Button>
      }
      className={className}
    />
  )
}

/**
 * Something could not be loaded: not found, not allowed, or another error,
 * with a way to try again, or to go back.
 */
export function ErrorState({
  error,
  onRetry,
  back,
  framed,
  className,
}: {
  error: unknown
  onRetry?: () => void
  back?: ReactNode
  framed?: boolean
  className?: string
}) {
  if (isApiError(error) && error.status === 404) {
    return <StateView icon={<FileQuestion />} title={t("notFound")} description={t("notFoundHint")} action={back} framed={framed} className={className} />
  }
  if (isApiError(error) && error.status === 403) {
    return <StateView tone="warning" icon={<ShieldX />} title={t("forbidden")} description={t("forbiddenPage")} action={back} framed={framed} className={className} />
  }
  return (
    <StateView
      tone="error"
      framed={framed}
      icon={<AlertTriangle />}
      title={t("loadFailed")}
      description={describe(error)}
      action={
        <>
          {back}
          {onRetry && (
            <Button variant="outline" onClick={onRetry}>
              <RotateCw /> {t("retry")}
            </Button>
          )}
        </>
      }
      className={className}
    />
  )
}

/** What was shown could not be refreshed: it stays, and this says so. */
export function RefreshError({ error, onRetry }: { error: unknown; onRetry: () => void }) {
  return (
    <Alert variant="destructive" className="animate-in fade-in-0">
      <AlertTriangle />
      <AlertTitle>{t("refreshFailed")}</AlertTitle>
      <AlertDescription className="flex flex-wrap items-center justify-between gap-2">
        <span>
          {t("staleData")} {describe(error)}
        </span>
        <Button variant="outline" size="sm" onClick={onRetry}>
          <RotateCw /> {t("retry")}
        </Button>
      </AlertDescription>
    </Alert>
  )
}

/** A thin bar moving across the top of what is loading again. */
export function LoadingBar({ active }: { active: boolean }) {
  return (
    <div className="pointer-events-none absolute inset-x-0 top-0 z-10 h-0.5 overflow-hidden" aria-hidden={!active}>
      <div
        className={cn(
          "h-full w-1/3 rounded-full bg-primary transition-opacity duration-300",
          active ? "animate-[loading-bar_1.1s_ease-in-out_infinite] opacity-100" : "opacity-0",
        )}
      />
      <span className="sr-only" role="status">
        {active ? t("loading") : ""}
      </span>
    </div>
  )
}

/** The rows of a table, loading. */
export function TableSkeleton({ columns, rows = 5 }: { columns: number; rows?: number }) {
  return (
    <>
      {Array.from({ length: rows }, (_, i) => (
        <tr key={i} className="border-b">
          {Array.from({ length: columns }, (_, j) => (
            <td key={j} className="p-2">
              <Skeleton className="h-5" style={ { width: `${50 + ((i * 7 + j * 13) % 40)}%` } } />
            </td>
          ))}
        </tr>
      ))}
    </>
  )
}

/** A form, loading. */
export function FormSkeleton({ fields = 4 }: { fields?: number }) {
  return (
    <div className="flex max-w-2xl flex-col gap-6" role="status" aria-label={t("loading")}>
      <Skeleton className="h-8 w-56" />
      <Card>
        <CardContent className="flex flex-col gap-6">
          {Array.from({ length: fields }, (_, i) => (
            <div key={i} className="flex flex-col gap-2">
              <Skeleton className="h-4 w-24" />
              <Skeleton className="h-9 w-full" />
            </div>
          ))}
        </CardContent>
      </Card>
    </div>
  )
}

/** A record's page, loading. */
export function DetailSkeleton({ fields = 6 }: { fields?: number }) {
  return (
    <div className="flex flex-col gap-6" role="status" aria-label={t("loading")}>
      <div className="flex items-center justify-between">
        <div className="flex flex-col gap-2">
          <Skeleton className="h-8 w-64" />
          <Skeleton className="h-4 w-24" />
        </div>
        <Skeleton className="h-9 w-40" />
      </div>
      <Card>
        <CardContent className="grid gap-x-8 gap-y-6 sm:grid-cols-2">
          {Array.from({ length: fields }, (_, i) => (
            <div key={i} className="flex flex-col gap-2">
              <Skeleton className="h-4 w-20" />
              <Skeleton className="h-5 w-40" />
            </div>
          ))}
        </CardContent>
      </Card>
    </div>
  )
}
